const item = $input.first().json;
const body = item.body || item;

const reference = body.reference;
const claimId = body.claimId;
const clientName = body.clientName;
const clientCompany = body.clientCompany || 'N/A';
const clientEmail = body.clientEmail;
const clientPhone = body.clientPhone || 'N/A';
const clientWilaya = body.clientWilaya || 'N/A';
const equipmentName = body.equipmentName || 'N/A';
const equipmentType = body.equipmentType || 'N/A';
const incidentDate = body.incidentDate ? new Date(body.incidentDate).toLocaleDateString('fr-DZ') : 'N/A';
const claimedAmount = body.claimedAmount ? `${Number(body.claimedAmount).toLocaleString('fr-DZ')} DA` : 'N/A';
const description = body.description || 'N/A';
const notes = body.notes || 'N/A';
const decidedAt = body.decidedAt ? new Date(body.decidedAt).toLocaleString('fr-DZ') : new Date().toLocaleString('fr-DZ');
const decidedDate = body.decidedAt
  ? new Date(body.decidedAt).toLocaleDateString('fr-DZ', { year: 'numeric', month: 'long', day: 'numeric' })
  : new Date().toLocaleDateString('fr-DZ', { year: 'numeric', month: 'long', day: 'numeric' });

const anomalyScore        = body.anomalyScore        != null ? Math.round(body.anomalyScore)        : null;
const classificationScore = body.classificationScore != null ? Math.round(body.classificationScore) : null;
const nlpScore            = body.nlpScore            != null ? Math.round(body.nlpScore)            : null;
const visionScore         = body.visionScore         != null ? Math.round(body.visionScore)         : null;
const finalScore          = body.finalScore          != null ? Math.round(body.finalScore)          : null;
const fraudClass          = body.fraudClass || 'N/A';

const scoreRow = (label, weight, score) => score != null ? `
  <tr>
    <td>${label}</td>
    <td style="text-align:center">${weight}</td>
    <td style="text-align:center;font-weight:bold">${score}/100</td>
    <td style="width:130px">
      <div style="background:#dde3ee;border-radius:3px;height:8px;width:100%">
        <div style="background:#1A7A4A;border-radius:3px;height:8px;width:${score}%"></div>
      </div>
    </td>
  </tr>` : '';

const html = `
