    /* ── HEADER ── */
    .header-band {
      background: #0F2347;
      padding: 20px 30px 14px;
      display: flex;
      justify-content: space-between;
      align-items: flex-start;
    }
    .logo-block { color: #fff; }
    .logo-name  { font-size: 18px; font-weight: bold; letter-spacing: .5px; }
    .logo-sub   { font-size: 9px; color: #C9A84C; margin-top: 3px; letter-spacing: 1px; text-transform: uppercase; }
    .title-block { text-align: center; color: #fff; }
    .title-block h1 { font-size: 14px; font-weight: bold; text-transform: uppercase; letter-spacing: .5px; }
    .title-block h2 { font-size: 10px; color: #a0b0cc; margin-top: 4px; }
