    .score-pill {
      background: #0F2347;
      color: #C9A84C;
      padding: 7px 18px;
      border-radius: 4px;
      font-size: 13px;
      font-weight: bold;
      text-align: center;
    }
    .score-pill span { display:block; font-size:9px; color:#a0b0cc; font-weight:normal; margin-top:2px; }

